static boolean canJump(int[] nums) {
  int reach = 0;
  for (int i = 0; i < nums.length; i++) {
    if (i > reach) return false;
    reach = Math.max(reach, i + nums[i]);
  }
  return true;
}

static List<List<Integer>> subsets(int[] nums) {
  List<List<Integer>> res = new ArrayList<>();
  go(nums, 0, new ArrayList<>(), res);
  return res;
}
static void go(int[] nums, int start, List<Integer> cur, List<List<Integer>> res) {
  res.add(new ArrayList<>(cur));
  for (int i = start; i < nums.length; i++) {
    cur.add(nums[i]); go(nums, i + 1, cur, res); cur.remove(cur.size() - 1);
  }
}

static List<List<Integer>> combinationSum(int[] cands, int target) {
  Arrays.sort(cands);
  List<List<Integer>> res = new ArrayList<>();
  go(cands, 0, target, new ArrayList<>(), res);
  return res;
}
static void go(int[] c, int start, int rem, List<Integer> cur, List<List<Integer>> res) {
  if (rem == 0) { res.add(new ArrayList<>(cur)); return; }
  for (int i = start; i < c.length; i++) {
    if (c[i] > rem) break;
    cur.add(c[i]); go(c, i, rem - c[i], cur, res); cur.remove(cur.size() - 1);
  }
}

static boolean exist(char[][] board, String word) {
  for (int r = 0; r < board.length; r++)
    for (int c = 0; c < board[0].length; c++)
      if (dfs(board, word, r, c, 0)) return true;
  return false;
}
static boolean dfs(char[][] b, String w, int r, int c, int i) {
  if (i == w.length()) return true;
  if (r < 0 || c < 0 || r >= b.length || c >= b[0].length || b[r][c] != w.charAt(i)) return false;
  char saved = b[r][c];
  b[r][c] = '#';
  boolean found = dfs(b, w, r + 1, c, i + 1) || dfs(b, w, r - 1, c, i + 1)
               || dfs(b, w, r, c + 1, i + 1) || dfs(b, w, r, c - 1, i + 1);
  b[r][c] = saved;
  return found;
}
